INSERT INTO order_daily_counter(store_id,business_date,last_pickup_no,updated_at) SELECT o.store_id,o.business_date,MAX(o.pickup_no),UTC_TIMESTAMP(6) FROM orders o JOIN ormo_qa_seed_registry r ON r.table_name='store' AND r.entity_id=o.store_id AND r.fixture_version='ormo-android-qa-v1' WHERE o.business_date IS NOT NULL GROUP BY o.store_id,o.business_date ON DUPLICATE KEY UPDATE last_pickup_no=GREATEST(last_pickup_no,VALUES(last_pickup_no)),updated_at=VALUES(updated_at);
